#### 2. Resilient Vendor Adapter
```typescript
// src/infrastructure/adapters/resilient-vendor-scorer.adapter.ts
import { PaymentScorerPort, ScoreRequest, ScoreResult } from '../../domain/ports/payment-scorer.port';

export interface ResilienceConfig {
  timeoutMs: number;
  maxConcurrentCalls: number;
  failureThresholdPercentage: number;
  resetTimeoutMs: number;
}

export class ResilientPaymentScorerAdapter implements PaymentScorerPort {
  private activeConcurrency = 0;
  private circuitState: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  private failureCount = 0;
  private totalCount = 0;
  private lastStateChange = Date.now();

  constructor(
    private readonly vendorHttpClient: (req: ScoreRequest, timeoutMs: number) => Promise<ScoreResult>,
    private readonly config: ResilienceConfig
  ) {}

  async evaluateRisk(request: ScoreRequest): Promise<ScoreResult> {
    this.checkCircuitReset();

    // 1. Circuit Breaker Fast-Fail
    if (this.circuitState === 'OPEN') {
      return this.executeFallback(request, 'Circuit Breaker OPEN');
    }

    // 2. Bulkhead Concurrency Guard
    if (this.activeConcurrency >= this.config.maxConcurrentCalls) {
      return this.executeFallback(request, 'Bulkhead Capacity Reached');
    }

    this.activeConcurrency++;
    try {
      // 3. Strict Timeout Wrapper
      const result = await this.callWithTimeout(request, this.config.timeoutMs);
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      return this.executeFallback(request, error instanceof Error ? error.message : 'Vendor Call Failed');
    } finally {
      this.activeConcurrency--;
    }
  }

  private async callWithTimeout(request: ScoreRequest, timeoutMs: number): Promise<ScoreResult> {
    return Promise.race([
      this.vendorHttpClient(request, timeoutMs),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error('Vendor Timeout Exceeded')), timeoutMs)
      ),
    ]);
  }

  private executeFallback(request: ScoreRequest, reason: string): ScoreResult {
    // Log metric/warning for operational monitoring
    console.warn(`[PaymentScorer] Fallback triggered: ${reason}`);
    return {
      score: 50, // Default neutral risk score
      riskTier: 'MEDIUM',
      isFallback: true,
    };
  }

  private recordSuccess(): void {
    this.totalCount++;
    if (this.circuitState === 'HALF_OPEN') {
      this.circuitState = 'CLOSED';
      this.failureCount = 0;
      this.totalCount = 0;
    }
  }

  private recordFailure(): void {
    this.failureCount++;
    this.totalCount++;

    const failureRate = (this.failureCount / this.totalCount) * 100;
    if (this.totalCount >= 10 && failureRate >= this.config.failureThresholdPercentage) {
      this.circuitState = 'OPEN';
      this.lastStateChange = Date.now();
    }
  }

  private checkCircuitReset(): void {
    if (this.circuitState === 'OPEN' && Date.now() - this.lastStateChange > this.config.resetTimeoutMs) {
      this.circuitState = 'HALF_OPEN';
    }
  }
}
```

