#### 2. Implement Cohesive, Single-Responsibility Steps (LCOM4 = 1, CC < 5)

```typescript
// src/domain/steps/TaxCalculationStep.ts
import { OrderProcessingStep, OrderContext, StepResult } from '../pipeline/types.js';

export interface ITaxCalculator {
  calculateTax(context: OrderContext): Promise<number>;
}

export class TaxCalculationStep implements OrderProcessingStep {
  readonly name = 'TaxCalculation';

  constructor(private readonly taxCalculator: ITaxCalculator) {}

  async execute(context: OrderContext): Promise<StepResult> {
    try {
      context.taxAmount = await this.taxCalculator.calculateTax(context);
      context.totalAmount += context.taxAmount;
      return { success: true };
    } catch (err) {
      return { success: false, error: (err as Error).message };
    }
  }
}
```

```typescript
// src/domain/steps/PaymentStep.ts
import { OrderProcessingStep, OrderContext, StepResult } from '../pipeline/types.js';

export interface IPaymentGateway {
  charge(orderId: string, amount: number): Promise<{ paymentId: string; status: string }>;
}

export class PaymentStep implements OrderProcessingStep {
  readonly name = 'PaymentProcessing';

  constructor(private readonly paymentGateway: IPaymentGateway) {}

  async execute(context: OrderContext): Promise<StepResult> {
    const response = await this.paymentGateway.charge(context.orderId, context.totalAmount);
    if (response.status !== 'SUCCESS') {
      return { success: false, error: `Payment failed with status ${response.status}` };
    }
    context.paymentId = response.paymentId;
    return { success: true };
  }
}
```

#### 3. Low-Complexity Pipeline Orchestrator (CC = 3)

```typescript
// src/domain/pipeline/OrderProcessingPipeline.ts
import { OrderProcessingStep, OrderContext, StepResult } from './types.js';

export class OrderProcessingPipeline {
  constructor(private readonly steps: OrderProcessingStep[]) {}

  async process(context: OrderContext): Promise<StepResult> {
    for (const step of this.steps) {
      const result = await step.execute(context);
      if (!result.success) {
        return {
          success: false,
          error: `[${step.name}] ${result.error ?? 'Step failed'}`
        };
      }
    }
    return { success: true };
  }
}
```

#### 4. Backward-Compatible Refactored `OrderProcessor` (Facade)

```typescript
// src/application/OrderProcessor.ts
import { OrderProcessingPipeline } from '../domain/pipeline/OrderProcessingPipeline.js';
import { TaxCalculationStep, ITaxCalculator } from '../domain/steps/TaxCalculationStep.js';
import { PaymentStep, IPaymentGateway } from '../domain/steps/PaymentStep.js';
import { OrderContext, StepResult } from '../domain/pipeline/types.js';

export class OrderProcessor {
  private readonly pipeline: OrderProcessingPipeline;

  constructor(
    taxCalculator: ITaxCalculator,
    paymentGateway: IPaymentGateway
  ) {
    this.pipeline = new OrderProcessingPipeline([
      new TaxCalculationStep(taxCalculator),
      new PaymentStep(paymentGateway)
    ]);
  }

  async processOrder(orderContext: OrderContext): Promise<StepResult> {
    return this.pipeline.process(orderContext);
  }
}
```

