    };
    const step = new TaxCalculationStep(mockTaxCalculator);
    const context = { orderId: '123', customerId: 'c1', items: [], totalAmount: 100.00, metadata: {} };

    const result = await step.execute(context);

    expect(result.success).toBe(true);
    expect(context.taxAmount).toBe(15.00);
